package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.repository.content.*;
import com.lianxibu.site.service.content.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;

class ReportResultDownstreamTest {
 ResultJdbcStoreTest f;ReportResultDownstream downstream;
 ResultJdbcStoreTest fixture(){return new ResultJdbcStoreTest();}
 @BeforeEach void setup(){f=fixture();f.fixture();var reads=new ContentReadService(new JdbcContentReads(f.source),f.tx,ContentReadService.denyUnverifiedReferences());downstream=new ReportResultDownstream(new JdbcFrozenInputs(f.source),new JdbcReportResults(f.source),reads,f.clock);var handler=new ContentResultHandler(new GeneratedContentService(new JdbcGeneratedContents(f.source),f.clock),f.store::context,downstream);f.service=new ResultApplicationService(f.writes,f.store,Map.of("report",handler,"analysis",handler,"dedup",handler,"value",handler,"ad_hoc",handler));}
 int ready(){return f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE target_type='report_result_ready'",Integer.class);}
 @Test void dailyCompletionAtomicallyCreatesOriginalWeeklyAndMonthlyIntentions(){assertEquals(ResultApplicationService.Status.APPLIED,f.apply().status());assertEquals(1,ready());assertEquals(List.of("2026-01-04","2026-01-31"),f.jdbc.query("SELECT business_date FROM jobs WHERE record_kind='generation_intent' AND task_type IN ('weekly_report','monthly_report') ORDER BY business_date",(r,n)->r.getDate(1).toString()));assertEquals(2,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent' AND task_type IN ('weekly_report','monthly_report') AND state='waiting_input' AND generation=1 AND call_count=0",Integer.class));f.apply();assertEquals(1,ready());assertEquals(3,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));}
 @Test void receiptFailureRollsBackBodyIntentsAndRetainedResult(){f.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_report_ready_failure CHECK(target_type IS NULL OR target_type<>'report_result_ready')");assertThrows(RuntimeException.class,f::apply);assertEquals(0,f.count("contents"));assertEquals(0,ready());assertEquals(1,f.jdbc.queryForObject("SELECT COUNT(*) FROM jobs WHERE record_kind='generation_intent'",Integer.class));assertNull(new JdbcResultState(f.source).root(ResultJdbcStoreTest.ROOT).resultHash());assertEquals("occupied",new JdbcWorkerState(f.source).slot().state());}
 @Test void wrongBodyOrAppliedIdentityCannotCreatePeriodIntentions(){var input=f.store.input();var context=f.store.context();var result=ResultApplicationService.validate(input,f.raw());assertThrows(RuntimeException.class,()->f.writes.execute(f.action("fictional-forged-report"),k->null,a->{downstream.afterApplied(input,context,result,new ResultApplicationService.Applied("fictional-other",1L));return true;}));assertEquals(0,ready());assertEquals(0,f.count("contents"));}
 @Test void naturalPeriodsHandleYearAndLeapMonthBoundaries(){assertEquals(List.of(LocalDate.parse("2023-01-01"),LocalDate.parse("2022-12-31")),ReportResultDownstream.periods(LocalDate.parse("2022-12-31")));assertEquals(List.of(LocalDate.parse("2024-03-03"),LocalDate.parse("2024-02-29")),ReportResultDownstream.periods(LocalDate.parse("2024-02-29")));}
 @Test void OriginalReadyReceiptTimestampIsUtcAcrossJvmDefaultsWithoutChangingPayloadOrReplay(){var original=TimeZone.getDefault();Instant now=Instant.parse("2026-01-01T21:00:00.123456Z");try{for(String zone:List.of("UTC","Asia/Shanghai","Asia/Tokyo","America/Los_Angeles")){setup();TimeZone.setDefault(TimeZone.getTimeZone(zone));var ledger=new JdbcReportResults(f.source);String root="fictional-time-report-root";var payload=tools.jackson.databind.json.JsonMapper.shared().createObjectNode().put("schema_version","report-result-ready-v1").put("fictional_timestamp_probe",true);f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-ready-utc-write",root,null),key->null,c->{ledger.save(root,payload,now);return true;});var actual=f.jdbc.queryForObject("SELECT acted_at FROM jobs WHERE target_type='report_result_ready'",(r,n)->r.getTimestamp(1,Calendar.getInstance(TimeZone.getTimeZone("UTC"))).toInstant());assertEquals(now,actual,zone);assertEquals(payload,ledger.read(root));f.writes.execute(new SharedWriteExecutor.ActionContext("fictional-ready-utc-replay",root,null),key->null,c->{ledger.save(root,payload,now.plusSeconds(1));return true;});assertEquals(1,ready());assertEquals(now,f.jdbc.queryForObject("SELECT created_at FROM jobs WHERE target_type='report_result_ready'",(r,n)->r.getTimestamp(1,Calendar.getInstance(TimeZone.getTimeZone("UTC"))).toInstant()));}}finally{TimeZone.setDefault(original);}}
}
